  `member_image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `member_researcharea` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `member_email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `member_website` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `member_country` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `member_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `member_designation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `member_publication_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `member_orcid_id` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `member_scopus_id` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `member_thomson_reuters` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `member_google_scholar_id` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `member_linkedin` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`member_id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
